encoded=''.join(CAPSULE.split())
assert len(encoded)==88685 and hashlib.sha256(encoded.encode()).hexdigest()=="56bb46a476d35128b4743224c5f015d13f38d99d50e319f9bef871878350cd94"
data=lzma.decompress(base64.b85decode(encoded))
assert len(data)==312622 and hashlib.sha256(data).hexdigest()=="617f94b82a54bf54cd7cce67fbf5d506cc3d2b9431a7c64b587984ea429992f6"
files=json.loads(data);assert len(files)==76
root=Path(sys.argv[1]);root.mkdir(parents=True,exist_ok=False)
for name,text in files.items():
 relative=Path(name);assert not relative.is_absolute() and '..' not in relative.parts
 p=root/relative;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(text.encode())
print('VQ20_C622_LITERAL_SOURCE_CAPSULE_RECOVERED',len(files),root)
